<?php
$appPage='transactions';$appTitle='Transactions';require __DIR__.'/../includes/customer_header.php';$type=trim($_GET['type']??'');$status=trim($_GET['status']??'');$search=trim($_GET['search']??'');$page=max(1,(int)($_GET['page']??1));$perPage=20;$where=['user_id=?'];$params=[$customerId];if($type!==''){$where[]='type=?';$params[]=$type;}if($status!==''){$where[]='status=?';$params[]=$status;}if($search!==''){$where[]='(reference LIKE ? OR description LIKE ?)';$params[]='%'.$search.'%';$params[]='%'.$search.'%';}$count=$pdo->prepare('SELECT COUNT(*) FROM financial_transactions WHERE '.implode(' AND ',$where));$count->execute($params);$total=(int)$count->fetchColumn();$sql='SELECT * FROM financial_transactions WHERE '.implode(' AND ',$where).' ORDER BY created_at DESC LIMIT ? OFFSET ?';$stmt=$pdo->prepare($sql);$i=1;foreach($params as $value)$stmt->bindValue($i++,$value,is_int($value)?PDO::PARAM_INT:PDO::PARAM_STR);$stmt->bindValue($i++,$perPage,PDO::PARAM_INT);$stmt->bindValue($i,($page-1)*$perPage,PDO::PARAM_INT);$stmt->execute();
?><section class="panel"><form method="get" class="form-grid"><div class="field"><label for="search">Search</label><input id="search" name="search" value="<?=e($search)?>"></div><div class="field"><label for="type">Type</label><select id="type" name="type"><option value="">All types</option><?php foreach(['card_funding','card_transfer','credit_disbursement','credit_repayment'] as $v):?><option value="<?=$v?>" <?=$type===$v?'selected':''?>><?=e(str_replace('_',' ',$v))?></option><?php endforeach?></select></div><div class="field"><label for="status">Status</label><select id="status" name="status"><option value="">All statuses</option><?php foreach(['processing','completed','failed','reversed'] as $v):?><option value="<?=$v?>" <?=$status===$v?'selected':''?>><?=$v?></option><?php endforeach?></select></div><div class="field" style="align-self:end"><button class="button button-secondary">Apply filters</button></div></form><div class="actions" style="margin:18px 0"><a class="button button-secondary" href="statement.php">Download CSV statement</a></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Reference</th><th>Type</th><th>Amount</th><th>Fee</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($stmt->fetchAll() as $row):?><tr><td><a href="transaction.php?reference=<?=urlencode($row['reference'])?>"><?=e($row['reference'])?></a></td><td><?=e(str_replace('_',' ',$row['type']))?></td><td class="money"><?=Money::format((int)$row['amount_cents'])?></td><td><?=Money::format((int)$row['fee_cents'])?></td><td><span class="badge <?=e($row['status'])?>"><?=e($row['status'])?></span></td><td><?=e($row['created_at'])?></td></tr><?php endforeach?></tbody></table></div><p class="muted"><?=e($total)?> matching transactions.</p></section><?php require __DIR__.'/../includes/customer_footer.php';?>
